def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('transform_verb') or needverb(nb.get('task_type', ''))[0]
    tool = nb.get('transform_tool') or needverb(nb.get('task_type', ''))[1]
    msg = ''
    if stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here; take it before opening or visiting more places.'
    elif stage == 'transform' and target and verb and tool:
        msg = 'You are carrying the ' + target + '; use the ' + tool + ' to ' + verb + ' it before placing it.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are carrying the ' + target + '; put it in/on the ' + dest + ' now.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to the ' + dest + ' and avoid unrelated containers.'
    elif stage == 'wrong_inventory' and target:
        msg = 'You appear to be carrying a non-target item; do not place it as the goal. Recover and find a ' + target + '.'
    elif stage == 'find_target' and target and val(ctx, 'world.target_found', False):
        msg = 'The ' + target + ' has been found; navigate to it and take it when its take action appears.'
    elif stage == 'find_target' and target and (val(ctx, 'predicates.same_action_repeated', False) or val(ctx, 'predicates.same_observation_repeated', False) or val(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited receptacles for the ' + target + ', but take it immediately when its take action appears.'
    elif stage == 'find_target' and target and val(ctx, 'world.placed_count', 0) > 0 and 'two' in nb.get('task_type', '') and val(ctx, 'predicates.same_action_repeated', False):
        msg = 'One ' + target + ' is already placed; do not take it back. Find another ' + target + ' and use the same destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:50]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

